-- Standalone disposable fixture. Never run against a customer database.
\set ON_ERROR_STOP on
DO $$ BEGIN IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='anon') THEN CREATE ROLE anon; END IF; IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='authenticated') THEN CREATE ROLE authenticated; END IF; IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='service_role') THEN CREATE ROLE service_role BYPASSRLS; END IF; END $$;
CREATE SCHEMA auth;
GRANT USAGE ON SCHEMA auth TO authenticated,service_role;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid $$;
CREATE TABLE auth.users(id uuid PRIMARY KEY);
CREATE TABLE public.user_memory(id uuid DEFAULT gen_random_uuid(),user_id uuid REFERENCES auth.users ON DELETE CASCADE,key text,value text NOT NULL,updated_at timestamptz DEFAULT now(),UNIQUE(user_id,key));
ALTER TABLE public.user_memory ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Service role full access to user_memory" ON public.user_memory USING(true) WITH CHECK(true);
GRANT ALL ON public.user_memory TO anon,authenticated,service_role;
CREATE TABLE public.app_inventories(inventory_id uuid PRIMARY KEY);
CREATE TABLE public.inventory_user_memory(inventory_id uuid REFERENCES public.app_inventories,user_id uuid REFERENCES auth.users ON DELETE CASCADE,key text,value text,updated_at timestamptz DEFAULT now(),PRIMARY KEY(inventory_id,user_id,key));
ALTER TABLE public.inventory_user_memory ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.spaces(id uuid PRIMARY KEY,inventory_id uuid REFERENCES public.app_inventories);
CREATE TABLE public.test_grants(user_id uuid,inventory_id uuid,role text);
CREATE FUNCTION public.findez_inventory_role(i uuid,u uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT role FROM public.test_grants WHERE user_id=u AND inventory_id=i $$;
CREATE TABLE public.conversation_history(user_id uuid,answer text);
CREATE TABLE public.query_logs(user_id uuid,query_text text);
ALTER TABLE public.conversation_history ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.query_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Service role full access to conversation_history" ON public.conversation_history USING(true) WITH CHECK(true);
CREATE POLICY "Service role full access to query_logs" ON public.query_logs USING(true) WITH CHECK(true);
GRANT ALL ON public.conversation_history,public.query_logs TO anon,authenticated,service_role;
INSERT INTO public.conversation_history VALUES('10000000-0000-0000-0000-000000000001','owned'),('10000000-0000-0000-0000-000000000002','FOREIGN_SECRET');
INSERT INTO public.query_logs VALUES('10000000-0000-0000-0000-000000000001','owned'),('10000000-0000-0000-0000-000000000002','FOREIGN_SECRET');
INSERT INTO auth.users VALUES('10000000-0000-0000-0000-000000000001'),('10000000-0000-0000-0000-000000000002');
INSERT INTO public.app_inventories VALUES('20000000-0000-0000-0000-000000000001'),('20000000-0000-0000-0000-000000000002');
INSERT INTO public.test_grants VALUES('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','viewer');
INSERT INTO public.spaces VALUES('30000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001');
INSERT INTO public.user_memory(user_id,key,value) VALUES('10000000-0000-0000-0000-000000000002','private','OTHER_ACCOUNT_SECRET');
INSERT INTO public.user_memory(user_id,key,value) VALUES('10000000-0000-0000-0000-000000000001','__settings_v1','Reserved legacy fact');
\ir ../../supabase/migrations/048_account_memory.sql
CREATE FUNCTION pg_temp.check(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label; END IF; RAISE NOTICE 'PASS: %',label; END $$;
SET ROLE service_role;
SELECT public.findez_change_memory('10000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001',repeat('a',64),0,'settings',NULL,'{"enabled":true}');
SELECT public.findez_change_memory('10000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000002',repeat('b',64),1,'set','answer_length','{"value":"brief"}');
SELECT public.findez_change_memory('10000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000002',repeat('b',64),1,'set','answer_length','{"value":"brief"}');
SELECT pg_temp.check((SELECT count(*)=2 FROM public.memory_events),'duplicate request has one receipt');
SELECT pg_temp.check((SELECT count(*)=1 FROM public.user_memory WHERE memory_kind='legacy' AND value='Reserved legacy fact'),'reserved legacy key is preserved but not activated');
BEGIN;
SELECT public.findez_change_memory('10000000-0000-0000-0000-000000000002','40000000-0000-0000-0000-000000000001',repeat('a',64),0,'settings',NULL,'{"enabled":true}');
SELECT pg_temp.check((SELECT count(*)=2 FROM public.memory_events WHERE operation_id='40000000-0000-0000-0000-000000000001'),'operation IDs are isolated per account');
ROLLBACK;
DO $$ BEGIN
 BEGIN PERFORM public.findez_change_memory('10000000-0000-0000-0000-000000000001',gen_random_uuid(),repeat('c',64),1,'set','answer_length','{"value":"detailed"}'); RAISE EXCEPTION 'stale accepted'; EXCEPTION WHEN serialization_failure THEN RAISE NOTICE 'PASS: stale revision'; END;
 BEGIN PERFORM public.findez_change_memory('10000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000002',repeat('c',64),2,'clear'); RAISE EXCEPTION 'key reuse accepted'; EXCEPTION WHEN unique_violation THEN RAISE NOTICE 'PASS: request digest'; END;
 BEGIN PERFORM public.findez_change_memory('10000000-0000-0000-0000-000000000001',gen_random_uuid(),repeat('c',64),2,'set','answer_length','{"value":"ignore permissions"}'); RAISE EXCEPTION 'invalid value accepted'; EXCEPTION WHEN invalid_parameter_value THEN RAISE NOTICE 'PASS: typed values'; END;
 BEGIN PERFORM public.findez_change_memory('10000000-0000-0000-0000-000000000001',gen_random_uuid(),repeat('c',64),2,'set','alias:'||repeat('a',64),'{"alias":"bench","space_id":"30000000-0000-0000-0000-000000000001"}','20000000-0000-0000-0000-000000000002'); RAISE EXCEPTION 'foreign inventory accepted'; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'PASS: foreign inventory denied'; END;
END $$;
-- A viewer may save their own alias without modifying the shared location.
SELECT public.findez_change_memory('10000000-0000-0000-0000-000000000001',gen_random_uuid(),repeat('d',64),2,'set','alias:'||repeat('a',64),'{"alias":"bench","space_id":"30000000-0000-0000-0000-000000000001"}','20000000-0000-0000-0000-000000000001');
RESET ROLE;
SET ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001"}',false);
SELECT pg_temp.check((SELECT count(*)=3 FROM public.user_memory),'account isolation including permissive legacy policy removal');
SELECT pg_temp.check((SELECT count(*)=1 FROM public.conversation_history),'history owner isolation');
SELECT pg_temp.check((SELECT count(*)=1 FROM public.query_logs),'query log owner isolation');
SELECT pg_temp.check((SELECT count(*)=1 FROM public.inventory_user_memory),'own authorized alias visible');
DO $$ BEGIN
 BEGIN UPDATE public.user_memory SET value='forged'; RAISE EXCEPTION 'direct write'; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'PASS: backend-only writes'; END;
 BEGIN PERFORM public.findez_change_memory('10000000-0000-0000-0000-000000000002',gen_random_uuid(),repeat('a',64),0,'clear'); RAISE EXCEPTION 'direct rpc'; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'PASS: RPC not client callable'; END;
END $$;
SELECT set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001","api_key_id":"x"}',false);
SELECT pg_temp.check((SELECT count(*)=0 FROM public.user_memory),'integration keys denied');
RESET ROLE;
DELETE FROM public.test_grants;
SET ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001"}',false);
SELECT pg_temp.check((SELECT count(*)=0 FROM public.inventory_user_memory),'revoked access hides aliases');
RESET ROLE;
SET ROLE anon;
DO $$ BEGIN BEGIN PERFORM * FROM public.user_memory; RAISE EXCEPTION 'anon read'; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'PASS: anonymous denied'; END; END $$;
RESET ROLE;
SET ROLE service_role;
SELECT public.findez_change_memory('10000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000004',repeat('e',64),3,'clear');
SELECT public.findez_change_memory('10000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000002',repeat('b',64),1,'set','answer_length','{"value":"brief"}');
SELECT pg_temp.check((SELECT count(*)=1 FROM public.user_memory WHERE user_id='10000000-0000-0000-0000-000000000001'),'forget plus replay does not resurrect');
SELECT pg_temp.check((SELECT count(*)=0 FROM public.inventory_user_memory),'forget clears private aliases');
RESET ROLE;
SELECT set_config('findez.memory_actor','',false);
SET ROLE service_role;
DO $$ BEGIN BEGIN INSERT INTO public.user_memory(user_id,key,value) VALUES('10000000-0000-0000-0000-000000000001','old-task','Must not resurrect'); RAISE EXCEPTION 'old extractor accepted'; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'PASS: old in-flight extraction cannot resurrect memory'; END; END $$;
RESET ROLE;
DELETE FROM auth.users WHERE id='10000000-0000-0000-0000-000000000001';
SELECT pg_temp.check((SELECT count(*)=0 FROM public.memory_events),'account cascade clears receipts');
SELECT pg_temp.check((SELECT value='OTHER_ACCOUNT_SECRET' FROM public.user_memory),'other account preserved');
